from checkpoint_store import CheckpointStore
from export_models import ExportRecord, ExportSummary


class ExportRepository:
    def __init__(self, rows: list[ExportRecord]) -> None:
        self.rows = sorted(rows, key=lambda row: row.record_id)

    def page_after(self, after_id: int | None, limit: int) -> list[ExportRecord]:
        return [row for row in self.rows if after_id is None or row.record_id > after_id][:limit]


class ExportSink:
    def __init__(self, fail_on_page: int | None = None) -> None:
        self.fail_on_page = fail_on_page
        self.pages: list[list[int]] = []
        self.calls = 0

    def upload(self, export_id: str, rows: list[ExportRecord]) -> int:
        self.calls += 1
        if self.fail_on_page == self.calls:
            raise OSError("storage unavailable")
        ids = [row.record_id for row in rows]
        if ids not in self.pages:
            self.pages.append(ids)
        return ids[-1]


def run_export(export_id: str, repository: ExportRepository, sink: ExportSink, checkpoints: CheckpointStore, *, page_size: int) -> dict:
    uploaded = 0
    cursor = checkpoints.get(export_id)
    while True:
        page = repository.page_after(cursor, page_size)
        if not page:
            return ExportSummary(export_id, uploaded, checkpoints.get(export_id), "complete").as_dict()
        cursor = page[-1].record_id
        checkpoints.set(export_id, cursor)
        try:
            durable_id = sink.upload(export_id, page)
        except OSError:
            return ExportSummary(export_id, uploaded, checkpoints.get(export_id), "failed").as_dict()
        uploaded += len(page)

