from typing import Any


@dataclass
class RepositoryRecord:
    identifier: str
    state: str = "new"
    labels: tuple[str, ...] = ()
    metadata: dict[str, Any] = field(default_factory=dict)

    def with_state(self, state: str) -> "RepositoryRecord":
        return RepositoryRecord(
            identifier=self.identifier,
            state=state,
            labels=self.labels,
            metadata=dict(self.metadata),
        )

    def add_label(self, label: str) -> "RepositoryRecord":
        normalized = normalize_label(label)
        labels = tuple(dict.fromkeys((*self.labels, normalized)))
        return RepositoryRecord(
            identifier=self.identifier,
            state=self.state,
            labels=labels,
            metadata=dict(self.metadata),
        )


class RepositoryLedger:
    def __init__(self) -> None:
        self._records: dict[str, RepositoryRecord] = {}

    def save(self, record: RepositoryRecord) -> None:
        self._records[record.identifier] = record

    def get(self, identifier: str) -> RepositoryRecord | None:
        return self._records.get(identifier)

    def values(self) -> list[RepositoryRecord]:
        return list(self._records.values())

    def count_by_state(self, state: str) -> int:
        return sum(1 for record in self._records.values() if record.state == state)


def normalize_label(label: str) -> str:
    cleaned = str(label).strip().lower().replace(" ", "_")
    return cleaned or "unknown"


def parse_positive_int(value: Any, *, field_name: str) -> int:
    try:
        parsed = int(value)
    except (TypeError, ValueError) as exc:
        raise ValueError(f"{field_name} must be an integer") from exc
    if parsed < 0:
        raise ValueError(f"{field_name} must be non-negative")
    return parsed


def stable_partition(records: list[RepositoryRecord], state: str) -> tuple[list[RepositoryRecord], list[RepositoryRecord]]:
    matching: list[RepositoryRecord] = []
    remaining: list[RepositoryRecord] = []
    for record in records:
        if record.state == state:
            matching.append(record)
        else:
            remaining.append(record)
    return matching, remaining


def summarize(records: list[RepositoryRecord]) -> dict[str, int]:
    summary: dict[str, int] = {}
    for record in records:
        summary[record.state] = summary.get(record.state, 0) + 1
    return summary


