from checkpoint_store import CheckpointStore
from export_models import records
from export_workflow import ExportRepository, ExportSink, run_export


def test_complete_export_uploads_all_records():
    sink = ExportSink()
    result = run_export("ex1", ExportRepository(records(5)), sink, CheckpointStore(), page_size=2)
    assert result["status"] == "complete" and sum(map(len, sink.pages)) == 5


def test_checkpoint_after_complete_is_last_record():
    cp = CheckpointStore()
    run_export("ex1", ExportRepository(records(5)), ExportSink(), cp, page_size=2)
    assert cp.get("ex1") == 5


def test_failed_upload_does_not_advance_checkpoint_for_failed_page():
    cp = CheckpointStore(); sink = ExportSink(fail_on_page=2)
    run_export("ex1", ExportRepository(records(5)), sink, cp, page_size=2)
    assert cp.get("ex1") == 2


def test_resume_after_failure_uploads_missing_page():
    cp = CheckpointStore(); first = ExportSink(fail_on_page=2); repo = ExportRepository(records(5))
    run_export("ex1", repo, first, cp, page_size=2)
    second = ExportSink()
    run_export("ex1", repo, second, cp, page_size=2)
    assert second.pages[0] == [3, 4]


def test_resume_does_not_reupload_completed_page():
    cp = CheckpointStore(); first = ExportSink(fail_on_page=2); repo = ExportRepository(records(5))
    run_export("ex1", repo, first, cp, page_size=2)
    second = ExportSink(); run_export("ex1", repo, second, cp, page_size=2)
    assert [1, 2] not in second.pages


def test_final_partial_page_is_uploaded():
    sink = ExportSink(); run_export("ex1", ExportRepository(records(5)), sink, CheckpointStore(), page_size=2)
    assert sink.pages[-1] == [5]


def test_empty_export_completes_with_zero_uploads():
    assert run_export("ex1", ExportRepository([]), ExportSink(), CheckpointStore(), page_size=2)["uploaded"] == 0


def test_summary_keys_are_stable():
    assert set(run_export("ex1", ExportRepository([]), ExportSink(), CheckpointStore(), page_size=2)) == {"export_id", "uploaded", "checkpoint", "status"}


def test_export_ids_have_independent_checkpoints():
    cp = CheckpointStore()
    run_export("a", ExportRepository(records(2)), ExportSink(), cp, page_size=1)
    assert cp.get("b") is None


def test_records_are_uploaded_in_order():
    sink = ExportSink(); run_export("ex1", ExportRepository(list(reversed(records(4)))), sink, CheckpointStore(), page_size=2)
    assert sink.pages == [[1, 2], [3, 4]]


def test_common_wrong_fix_does_not_checkpoint_attempted_failed_page():
    cp = CheckpointStore(); run_export("ex1", ExportRepository(records(4)), ExportSink(fail_on_page=1), cp, page_size=2)
    assert cp.get("ex1") is None


def test_retry_completed_job_uploads_nothing_new():
    cp = CheckpointStore(); repo = ExportRepository(records(3)); sink1 = ExportSink()
    run_export("ex1", repo, sink1, cp, page_size=2)
    sink2 = ExportSink(); run_export("ex1", repo, sink2, cp, page_size=2)
    assert sink2.pages == []


def test_failure_summary_reports_failed():
    assert run_export("ex1", ExportRepository(records(3)), ExportSink(fail_on_page=1), CheckpointStore(), page_size=2)["status"] == "failed"


def test_uploaded_count_excludes_failed_page():
    assert run_export("ex1", ExportRepository(records(4)), ExportSink(fail_on_page=2), CheckpointStore(), page_size=2)["uploaded"] == 2


def test_page_after_cursor_excludes_cursor_record():
    assert [r.record_id for r in ExportRepository(records(3)).page_after(1, 5)] == [2, 3]


def test_page_limit_is_respected():
    assert len(ExportRepository(records(5)).page_after(None, 2)) == 2


def test_checkpoint_store_can_clear_job():
    cp = CheckpointStore(); cp.set("x", 3); cp.clear("x")
    assert cp.get("x") is None


def test_sink_deduplicates_same_page_payload():
    sink = ExportSink(); repo = ExportRepository(records(2)); cp = CheckpointStore()
    run_export("x", repo, sink, cp, page_size=2); cp.clear("x"); run_export("x", repo, sink, cp, page_size=2)
    assert sink.pages == [[1, 2]]


def test_resume_after_second_page_failure_finishes_remaining_rows():
    cp = CheckpointStore(); repo = ExportRepository(records(6)); run_export("x", repo, ExportSink(fail_on_page=2), cp, page_size=2)
    sink = ExportSink(); run_export("x", repo, sink, cp, page_size=2)
    assert sink.pages == [[3, 4], [5, 6]]


def test_checkpoint_matches_durable_id_not_page_attempt():
    cp = CheckpointStore(); run_export("x", ExportRepository(records(2)), ExportSink(fail_on_page=1), cp, page_size=2)
    assert cp.get("x") is None
